Lemma entry_pc_matches : Z.of_N G.init_pc = 0x11158%Z.
Proof. vm_compute. reflexivity. Qed.

Lemma initial_integer_registers_match : forall rnd argv envp uid hw,
  map (fun i => bv_unsigned (ms_reg
    (init_machine_state G.loaded_segments G.init_pc G.phdrs observed_sp rnd argv envp uid hw)
    (Z_to_bv 5 (Z.of_nat i)))) (seq 0 32) = observed_gprs.
Proof. intros. vm_compute. reflexivity. Qed.

Lemma initial_floating_registers_match : forall rnd argv envp uid hw,
  map (fun i => bv_unsigned (reg_get (ms_fregs
    (init_machine_state G.loaded_segments G.init_pc G.phdrs observed_sp rnd argv envp uid hw))
    (Z_to_bv 5 (Z.of_nat i)))) (seq 0 32) = observed_fprs.
Proof. intros. vm_compute. reflexivity. Qed.

Lemma all_observed_instruction_words_match :
  map (fun pc => fetch_word G.loaded_segments (Z_to_bv 64 pc)) observed_pcs
  = map (fun w => Some (Z_to_bv 32 w)) observed_words.
Proof. vm_compute. reflexivity. Qed.


(* Data-state projection only. Instruction semantics remain published run_steps. *)
Definition observed_initial_machine rnd argv envp uid hw mem resv fcsr : machine_state :=
  let st := init_machine_state G.loaded_segments G.init_pc G.phdrs observed_sp rnd argv envp uid hw in
  {| ms_regs := ms_regs st; ms_fregs := ms_fregs st; ms_pc_val := ms_pc_val st;
     ms_svc_pending := ms_svc_pending st; ms_resv := resv; ms_fcsr := fcsr;
     ms_mem := mem; ms_rom := ms_rom st |}.

Definition project_registers (st : machine_state) : Z * (list Z * list Z) :=
  (bv_unsigned (ms_pc_val st),
   (map (fun i => bv_unsigned (ms_reg st (Z_to_bv 5 (Z.of_nat i)))) (seq 0 32),
    map (fun i => bv_unsigned (reg_get (ms_fregs st) (Z_to_bv 5 (Z.of_nat i)))) (seq 0 32))).
