Lemma every_observed_state_matches_published_steps : forall rnd argv envp uid hw mem resv fcsr,
  map (fun k => option_map project_registers
    (run_steps k G.loaded_segments
      (observed_initial_machine rnd argv envp uid hw mem resv fcsr))) (seq 0 21)
  = map Some observed_states.
Proof. intros. vm_compute. reflexivity. Qed.

(* Model computation after the last observed PRE-ecall state. This is not an
   additional observed CPU frame or a syscall-dispatch equivalence claim. *)
Lemma modeled_exit_syscall_request : forall rnd argv envp uid hw mem resv fcsr,
  option_map (fun st => (ms_svc_pending st, ms_reg st (Z_to_bv 5 10)))
    (run_steps 21 G.loaded_segments
      (observed_initial_machine rnd argv envp uid hw mem resv fcsr))
  = Some (Some (Z_to_bv 64 94), Z_to_bv 64 0).
Proof. intros. vm_compute. reflexivity. Qed.
